package cn.zhuatech.retail.service;import jakarta.validation.constraints.Min;import jakarta.validation.constraints.NotBlank;import org.springframework.stereotype.Service;import java.util.*;
@Service public class PromotionReleaseGovernanceService{public Assessment assess(Request r){List<String>b=new ArrayList<>(),a=new ArrayList<>();if(!r.priceApproved())b.add("促销价格未审批");if(r.projectedMarginBps()<r.minimumMarginBps())b.add("预计毛利率低于最低阈值");if(!r.taxRuleValidated())b.add("税务与含税展示规则未校验");if(!r.storeEligibilityConfigured())b.add("适用门店范围未配置");if(!r.startAndEndTimeValid())b.add("活动起止时间无效");if(!b.isEmpty()){a.add("阻止促销激活并修复价格、毛利、税务和范围配置");return new Assessment(Decision.BLOCKED,b,a);}if(!r.inventoryReserved()||!r.shelfLabelsReady()||!r.rollbackPlanReady()){if(!r.inventoryReserved())a.add("锁定门店与仓库促销库存");if(!r.shelfLabelsReady())a.add("同步价签和 POS 生效版本");if(!r.rollbackPlanReady())a.add("验证促销撤销与价格回滚");return new Assessment(Decision.REVIEW,b,a);}a.add("激活促销并冻结价格、门店、库存和时间快照");return new Assessment(Decision.ACTIVATE,b,a);}public record Request(@NotBlank String promotionCode,boolean priceApproved,@Min(0)int projectedMarginBps,@Min(0)int minimumMarginBps,boolean taxRuleValidated,boolean storeEligibilityConfigured,boolean startAndEndTimeValid,boolean inventoryReserved,boolean shelfLabelsReady,boolean rollbackPlanReady){}public record Assessment(Decision decision,List<String>blockers,List<String>actions){}public enum Decision{ACTIVATE,REVIEW,BLOCKED}}
